"""policy.ini (docs/policy.md)."""

import re
from datetime import timedelta, timezone

from logkeep import streams
from logkeep.errors import DataError

DEFAULTS = {"max_size": None, "max_age": None, "naming": "numbered", "offset": timezone.utc,
            "compress_after": 1, "keep": 5, "keep_days": None}
KEYS = set(DEFAULTS)
_INT = re.compile(r"[0-9]+\Z")
_SIZE = re.compile(r"([0-9]+)([KMGkmg]?)\Z")
_DUR = re.compile(r"([0-9]+)([mhd])\Z")
_OFF = re.compile(r"([+-])([0-9]{2}):([0-9]{2})\Z")


def _bad(msg):
    raise DataError("policy", msg)


def _value(key, v):
    if key in ("max_size", "max_age", "keep_days") and v == "off":
        return None
    if key == "max_size":
        m = _SIZE.match(v) or _bad(f"max_size: {v}")
        return int(m.group(1)) * {"": 1, "k": 1024, "m": 1024**2, "g": 1024**3}[m.group(2).lower()]
    if key == "max_age":
        m = _DUR.match(v) or _bad(f"max_age: {v}")
        return timedelta(**{{"m": "minutes", "h": "hours", "d": "days"}[m.group(2)]: int(m.group(1))})
    if key == "naming":
        if v not in ("numbered", "dated"):
            _bad(f"naming: {v}")
        return v
    if key == "offset":
        m = _OFF.match(v) or _bad(f"offset: {v}")
        h, mi = int(m.group(2)), int(m.group(3))
        if h > 23 or mi > 59:
            _bad(f"offset: {v}")
        d = timedelta(hours=h, minutes=mi)
        return timezone(-d if m.group(1) == "-" else d)
    if not _INT.match(v):
        _bad(f"{key}: {v}")
    n = int(v)
    if key in ("keep", "keep_days") and n < 1:
        _bad(f"{key}: {v}")
    return n


def load(path):
    """Returns (defaults dict, {stream: own settings dict}, set of stream names with a section)."""
    defaults, own = {}, {}
    if not path.exists():
        return defaults, own
    try:
        text = path.read_text(encoding="utf-8")
    except (OSError, UnicodeDecodeError) as e:
        _bad(f"{path.name}: {e}")
    cur = None
    seen_defaults = False
    for raw in text.splitlines():
        line = raw.strip()
        if not line or line[0] in "#;":
            continue
        if line.startswith("["):
            if not line.endswith("]"):
                _bad(f"bad section line: {line}")
            title = line[1:-1]
            if title == "defaults":
                if seen_defaults:
                    _bad("section [defaults] twice")
                seen_defaults = True
                cur = defaults
            elif title.startswith("stream ") and streams.valid(title[7:]):
                name = title[7:]
                if name in own:
                    _bad(f"section {title} twice")
                cur = own[name] = {}
            else:
                _bad(f"unknown section: {title}")
            continue
        if cur is None or "=" not in line:
            _bad(f"bad line: {line}")
        k, v = (s.strip() for s in line.split("=", 1))
        if k not in KEYS:
            _bad(f"unknown key: {k}")
        if k in cur:
            _bad(f"key twice: {k}")
        cur[k] = _value(k, v)
    return defaults, own


def settings(defaults, own, name):
    out = dict(DEFAULTS)
    out.update(defaults)
    out.update(own.get(name, {}))
    return out
