"""rotate (docs/rotate.md)."""

import gzip
import re
from datetime import date, datetime, timedelta, timezone

from logkeep import dates, policy, state, streams
from logkeep.errors import DataError, Refused

_ISO = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]+)?(Z|[+-][0-9]{2}:[0-9]{2})\Z")
_OLD = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2} [0-9]{2}:[0-9]{2}:[0-9]{2}\Z")


def parse_time(text, allow_old=True):
    """A time of data.md section 2 as an aware datetime, or None."""
    if not isinstance(text, str):
        return None
    try:
        if _ISO.match(text):
            t = datetime.fromisoformat(text[:-1] + "+00:00" if text.endswith("Z") else text)
        elif allow_old and _OLD.match(text):
            t = datetime.fromisoformat(text).replace(tzinfo=timezone.utc)
        else:
            return None
    except ValueError:
        return None
    return t if t.tzinfo is not None else None


class Arc:
    def __init__(self, name, key, gz):
        self.name, self.key, self.gz = name, key, gz
        self.new = False
        self.time = None  # time text in state
        self.final = None
        self.compress = False


def find_archives(logs, name, naming):
    out = []
    if not logs.is_dir():
        return out
    n = re.escape(name)
    if naming == "numbered":
        rx = re.compile(rf"{n}\.log\.([1-9][0-9]*)(\.gz)?\Z")
    else:
        rx = re.compile(rf"{n}\.log\.([0-9]{{4}}-[0-9]{{2}}-[0-9]{{2}})(?:\.([2-9]|[1-9][0-9]+))?(\.gz)?\Z")
    for p in logs.iterdir():
        if not p.is_file():
            continue
        m = rx.match(p.name)
        if not m:
            continue
        if naming == "numbered":
            out.append(Arc(p.name, (int(m.group(1)),), bool(m.group(2))))
        else:
            try:
                y, mo, d = (int(x) for x in m.group(1).split("-"))
                day = date(y, mo, d)
            except ValueError:
                continue
            out.append(Arc(p.name, (day, int(m.group(2) or 1)), bool(m.group(3))))
    return out


def run(ctx, names, dry, force):
    data, now = ctx.data, ctx.now
    logs = streams.logs_dir(data)
    defaults, own = policy.load(ctx.policy_path)
    doc = ctx.state
    existing = set(streams.active(data)) | set(own)
    entries = doc["streams"]
    for sname in existing:
        e = entries.get(sname)
        if e is None:
            continue
        bad = lambda m: DataError("state", f"{sname}: {m}")
        if "opened" in e and parse_time(e["opened"]) is None:
            raise bad("opened")
        if "archives" in e:
            if not isinstance(e["archives"], dict):
                raise bad("archives")
            for k, v in e["archives"].items():
                if parse_time(v) is None:
                    raise bad(f"archive time {k}")
        if "rotations" in e:
            r = e["rotations"]
            if not isinstance(r, int) or isinstance(r, bool) or r < 0:
                raise bad("rotations")
    if names:
        todo = sorted(set(names))
        for n in todo:
            if n not in existing:
                raise Refused("unknown-stream", f"no stream {n}")
    else:
        todo = sorted(existing)

    plans = []
    for sname in todo:
        cfg = policy.settings(defaults, own, sname)
        arcs = find_archives(logs, sname, cfg["naming"])
        seen = set()
        for a in arcs:
            if a.key in seen:
                raise DataError("archives", f"{sname}: two archives in the place {a.key}")
            seen.add(a.key)
        plans.append((sname, cfg, arcs))

    lines, writes_state = [], {}
    n_rot = n_rem = n_comp = 0
    ops_remove, ops_write = [], []  # file operations
    contents = {}
    for sname, cfg, arcs in plans:
        entry = entries.get(sname, {})
        times = entry.get("archives", {}) if isinstance(entry.get("archives", {}), dict) else {}
        logp = streams.log_path(data, sname)
        why = None
        if not logp.is_file():
            what = "no log"
        else:
            size = logp.stat().st_size
            if size == 0:
                what = "empty"
            elif force:
                what, why = "rotate (forced)", True
            elif cfg["max_size"] is not None and size >= cfg["max_size"]:
                what, why = "rotate (size)", True
            else:
                what = "not due"
                if cfg["max_age"] is not None:
                    opened = parse_time(entry["opened"]) if "opened" in entry else None
                    if opened is None and "opened" not in entry:
                        first = logp.read_bytes().split(b"\n", 1)[0]
                        tok = first.split(b" ", 1)[0]
                        try:
                            opened = parse_time(tok.decode("ascii"), allow_old=False)
                        except UnicodeDecodeError:
                            opened = None
                    if opened is not None and now - opened >= cfg["max_age"]:
                        what, why = "rotate (age)", True
        rotated = bool(why)
        for a in arcs:
            a.time = times.get(a.name)
        if rotated:
            n_rot += 1
            if cfg["naming"] == "numbered":
                for a in arcs:
                    a.key = (a.key[0] + 1,)
                key = (0,)
            else:
                day = now.astimezone(cfg["offset"]).date()
                same = [a.key[1] for a in arcs if a.key[0] == day]
                key = (day, max(same) + 1 if same else 1)
            na = Arc(None, key, False)
            na.new = True
            na.time = dates.stamp(now)
            arcs.append(na)
        arcs.sort(key=lambda a: a.key, reverse=True) if cfg["naming"] == "dated" else arcs.sort(key=lambda a: a.key)
        if cfg["naming"] == "dated":
            pass
        # newest first
        if cfg["naming"] == "dated":
            pass
        keep_arcs, removed = [], []
        for pos, a in enumerate(arcs, 1):
            drop = pos > cfg["keep"]
            if not drop and cfg["keep_days"] is not None and a.time is not None and not a.new:
                t = parse_time(a.time)
                if now - t >= timedelta(days=cfg["keep_days"]):
                    drop = True
            (removed if drop else keep_arcs).append(a)
        out = [f"{sname}: {what}"]
        new_times = {}
        for pos, a in enumerate(keep_arcs, 1):
            if a.new:
                a.name = None
            a.compress = (not a.gz) and pos > cfg["compress_after"]
            gz = a.gz or a.compress
            if cfg["naming"] == "numbered":
                a.final = f"{sname}.log.{pos}" + (".gz" if gz else "")
            else:
                d, k = a.key
                a.final = f"{sname}.log.{d.isoformat()}" + (f".{k}" if k > 1 else "") + (".gz" if gz else "")
            if a.compress:
                n_comp += 1
            if a.new:
                out.append(f"  new {a.final}")
            elif a.final != a.name:
                out.append(f"  {a.final} <- {a.name}")
            else:
                out.append(f"  {a.final}")
            if a.time is not None:
                new_times[a.final] = a.time
        for a in removed:
            out.append(f"  remove {a.name}")
            n_rem += 1
        lines += out
        # file operations
        if not dry:
            for a in removed:
                ops_remove.append(logs / a.name)
            if rotated:
                na = next(a for a in arcs if a.new)
                na.data = logp.read_bytes()
            for a in keep_arcs:
                if a.new:
                    raw = a.data
                elif a.final != a.name:
                    raw = (logs / a.name).read_bytes()
                else:
                    continue
                if a.compress:
                    raw = gzip.compress(raw, mtime=0)
                if not a.new:
                    ops_remove.append(logs / a.name)
                ops_write.append((logs / a.final, raw))
            if rotated:
                ops_write.append((logp, b""))
        ne = {}
        if rotated:
            ne["opened"] = dates.stamp(now)
        elif "opened" in entry:
            ne["opened"] = entry["opened"]
        ne["rotations"] = (entry.get("rotations", 0)) + (1 if rotated else 0)
        ne["archives"] = new_times
        writes_state[sname] = ne
    lines.append(f"{n_rot} rotated, {n_rem} removed, {n_comp} compressed")
    if dry:
        lines.append("dry run: nothing written")
        return lines
    for p in ops_remove:
        p.unlink()
    for p, raw in ops_write:
        p.write_bytes(raw)
    doc["streams"].update(writes_state)
    state.save(ctx.state_path, doc)
    return lines
